fn main() {
    let args = Args::parse();

    if args.version {
        println!("caesiumclt {}", env!("CARGO_PKG_VERSION"));
        return;
    }

    if args.help {
        println!("A fast and efficient lossy and/or lossless image compression tool\n");
        println!("Usage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n");
        println!("For full help, use --help");
        return;
    }

    // Validate required arguments
    let has_compression = args.quality.is_some() || args.lossless || args.max_size.is_some();
    let has_output = args.output.is_some() || args.same_folder_as_input;

    if !has_compression {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>");
        if !has_output {
            eprintln!("  <--output <OUTPUT>|--same-folder-as-input>");
        }
        eprintln!("\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n");
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    if !has_output {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <--output <OUTPUT>|--same-folder-as-input>\n");
        eprintln!("Usage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n");
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    // Set verbosity
    let verbose = if args.quiet { 0 } else { args.verbose };

    // Collect input files
    let input_files = collect_input_files(&args.files, args.recursive, verbose);

    if input_files.is_empty() {
        if verbose >= 1 {
            println!("No input files found");
        }
        return;
    }

    // Process files
    let results = process_files(input_files, &args, verbose);

    // Print results
    print_results(&results, verbose);
}

struct FileResult {
    input_path: PathBuf,
    output_path: PathBuf,
    original_size: u64,
    compressed_size: u64,
    success: bool,
    skipped: bool,
}

fn collect_input_files(paths: &[PathBuf], recursive: bool, verbose: u32) -> Vec<PathBuf> {
    let mut files = Vec::new();

    for path in paths {
        if path.is_file() {
            if is_supported_image(&path) {
                files.push(path.clone());
            }
        } else if path.is_dir() {
            if recursive {
                for entry in WalkDir::new(path)
                    .into_iter()
                    .filter_map(|e| e.ok())
                    .filter(|e| e.path().is_file())
                {
                    if is_supported_image(entry.path()) {
                        files.push(entry.path().to_path_buf());
                    }
                }
            } else {
                for entry in fs::read_dir(path).unwrap_or_default() {
                    if let Ok(entry) = entry {
                        let entry_path = entry.path();
                        if entry_path.is_file() && is_supported_image(&entry_path) {
                            files.push(entry_path);
                        }
                    }
                }
            }
        }
    }

    files
}

fn is_supported_image(path: &Path) -> bool {
    if let Some(ext) = path.extension() {
        if let Some(ext_str) = ext.to_str() {
            let lower = ext_str.to_lowercase();
            matches!(lower.as_str(), "jpg" | "jpeg" | "png" | "webp" | "gif" | "tif" | "tiff")
        } else {
            false
        }
    } else {
        false
    }
}

fn process_files(files: Vec<PathBuf>, args: &Args, verbose: u32) -> Vec<FileResult> {
    let results = files
        .into_par_iter()
        .map(|input_path| process_single_file(&input_path, args, verbose))
        .collect::<Vec<_>>();

    results
}

fn process_single_file(input_path: &Path, args: &Args, verbose: u32) -> FileResult {
    let original_size = fs::metadata(&input_path)
        .map(|m| m.len())
        .unwrap_or(0);

    let output_path = get_output_path(input_path, args);

    if !args.dry_run {
        // Create output directory if needed
        if let Some(parent) = output_path.parent() {
            let _ = fs::create_dir_all(parent);
        }

        // Try to compress and save the file
        match compress_and_save_image(input_path, &output_path, args) {
            Ok(compressed_size) => {
                if args.keep_dates {
                    let _ = preserve_timestamps(input_path, &output_path);
                }

                let compressed_size = fs::metadata(&output_path)
                    .map(|m| m.len())
                    .unwrap_or(compressed_size);

                if verbose >= 3 {
                    let delta = (compressed_size as i64) - (original_size as i64);
                    let percent = if original_size > 0 {
                        (delta as f64 / original_size as f64) * 100.0
                    } else {
                        0.0
                    };
                    println!("[Success] {} -> {}", input_path.display(), output_path.display());
                }

                FileResult {
                    input_path: input_path.to_path_buf(),
                    output_path,
                    original_size,
                    compressed_size,
                    success: true,
                    skipped: false,
                }
            }
            Err(e) => {
                if verbose >= 2 {
                    eprintln!("[Error] {}: {}", input_path.display(), e);
                }
                FileResult {
                    input_path: input_path.to_path_buf(),
                    output_path,
                    original_size,
                    compressed_size: original_size,
                    success: false,
                    skipped: false,
                }
            }
        }
    } else {
        // In dry-run mode, just simulate without writing
        FileResult {
            input_path: input_path.to_path_buf(),
            output_path,
            original_size,
            compressed_size: original_size,
            success: true,
            skipped: false,
        }
    }
}

fn get_output_path(input_path: &Path, args: &Args) -> PathBuf {
    let file_name = input_path.file_name().unwrap();
    let file_name_str = file_name.to_string_lossy().to_string();

    let output_name = if let Some(ref suffix) = args.suffix {
        if let Some(pos) = file_name_str.rfind('.') {
            format!("{}{}.{}", &file_name_str[..pos], suffix, &file_name_str[pos + 1..])
        } else {
            format!("{}{}", file_name_str, suffix)
        }
    } else if args.format != "original" {
        if let Some(pos) = file_name_str.rfind('.') {
            format!("{}.{}", &file_name_str[..pos], args.format)
        } else {
            format!("{}.{}", file_name_str, args.format)
        }
    } else {
        file_name_str
    };

    if args.same_folder_as_input {
        let input_dir = input_path.parent().unwrap_or_else(|| Path::new("."));
        input_dir.join(output_name)
    } else if let Some(ref output_dir) = args.output {
        if args.keep_structure && args.recursive {
            // Preserve directory structure
            // This is more complex and would need the original base path
            output_dir.join(output_name)
        } else {
            output_dir.join(output_name)
        }
    } else {
        PathBuf::from(output_name)
    }
}

fn compress_and_save_image(input_path: &Path, output_path: &Path, args: &Args) -> Result<u64, String> {
    // Load the image
    let img = image::open(input_path)
        .map_err(|e| format!("Failed to open image: {}", e))?;

    let mut img = img;

    // Apply resizing if needed
    if args.width.is_some() || args.height.is_some() || args.long_edge.is_some() || args.short_edge.is_some() {
        img = resize_image(img, args)?;
    }

    // Determine output format
    let output_format = if args.format != "original" {
        args.format.as_str()
    } else {
        output_path.extension()
            .and_then(|ext| ext.to_str())
            .unwrap_or("png")
    };

    // Determine quality
    let quality = if args.lossless {
        100
    } else {
        args.quality.unwrap_or(80)
    };

    // Save the image with the appropriate quality
    match output_format.to_lowercase().as_str() {
        "jpg" | "jpeg" => {
            img.save_with_format(output_path, image::ImageFormat::Jpeg)
                .map_err(|e| format!("Failed to save JPEG: {}", e))?;
        }
        "png" => {
            img.save_with_format(output_path, image::ImageFormat::Png)
                .map_err(|e| format!("Failed to save PNG: {}", e))?;
        }
        "webp" => {
            img.save_with_format(output_path, image::ImageFormat::WebP)
                .map_err(|e| format!("Failed to save WebP: {}", e))?;
        }
        "gif" => {
            img.save_with_format(output_path, image::ImageFormat::Gif)
                .map_err(|e| format!("Failed to save GIF: {}", e))?;
        }
        "tif" | "tiff" => {
            img.save_with_format(output_path, image::ImageFormat::Tiff)
                .map_err(|e| format!("Failed to save TIFF: {}", e))?;
        }
        _ => {
            return Err(format!("Unsupported output format: {}", output_format));
        }
    }

    let compressed_size = fs::metadata(output_path)
        .map(|m| m.len())
        .unwrap_or(0);

    Ok(compressed_size)
}

fn resize_image(img: image::DynamicImage, args: &Args) -> Result<image::DynamicImage, String> {
    let (width, height) = img.dimensions();

    let (new_width, new_height) = if let Some(long_edge) = args.long_edge {
        let (new_w, new_h) = if width >= height {
            (long_edge, (long_edge * height) / width)
        } else {
            ((long_edge * width) / height, long_edge)
        };
        (new_w, new_h)
    } else if let Some(short_edge) = args.short_edge {
        let (new_w, new_h) = if width <= height {
            (short_edge, (short_edge * height) / width)
        } else {
            ((short_edge * width) / height, short_edge)
        };
        (new_w, new_h)
    } else if args.width.is_some() && args.height.is_none() {
        let new_w = args.width.unwrap();
        let new_h = (new_w * height) / width;
        (new_w, new_h)
    } else if args.height.is_some() && args.width.is_none() {
        let new_h = args.height.unwrap();
        let new_w = (new_h * width) / height;
        (new_w, new_h)
    } else if let (Some(w), Some(h)) = (args.width, args.height) {
        (w, h)
    } else {
        (width, height)
    };

    if new_width == width && new_height == height {
        Ok(img)
    } else {
        Ok(img.resize_exact(new_width, new_height, image::imageops::FilterType::Lanczos3))
    }
}

fn preserve_timestamps(input_path: &Path, output_path: &Path) -> io::Result<()> {
    // In a real implementation, this would use filetime crate
    // For now, we'll skip this as it's platform-specific
    Ok(())
}

fn print_results(results: &[FileResult], verbose: u32) {
    let total = results.len();
    let success = results.iter().filter(|r| r.success && !r.skipped).count();
    let skipped = results.iter().filter(|r| r.skipped).count();
    let errors = total - success - skipped;

    let total_original: u64 = results.iter().map(|r| r.original_size).sum();
    let total_compressed: u64 = results.iter().map(|r| r.compressed_size).sum();
    let delta = (total_compressed as i64) - (total_original as i64);

    let percent = if total_original > 0 {
        (delta as f64 / total_original as f64) * 100.0
    } else {
        0.0
    };

    if verbose >= 1 {
        println!("Compressed {} files ({} success, {} skipped, {} errors)",
                 total, success, skipped, errors);

        let original_str = format_bytes(total_original);
        let compressed_str = format_bytes(total_compressed);
        let delta_str = if delta >= 0 {
            format!("+{}", format_bytes(delta as u64))
        } else {
            format!("-{}", format_bytes((-delta) as u64))
        };

        println!("{} -> {} [{} | {:.2}%]",
                 original_str, compressed_str, delta_str, percent);
    }
}

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}
