fn resize_image(img: image::DynamicImage, args: &Args) -> Result<image::DynamicImage, String> {
    let (width, height) = img.dimensions();

    let (new_width, new_height) = if let Some(long_edge) = args.long_edge {
        let (new_w, new_h) = if width >= height {
            (long_edge, (long_edge * height) / width)
        } else {
            ((long_edge * width) / height, long_edge)
        };
        (new_w, new_h)
    } else if let Some(short_edge) = args.short_edge {
        let (new_w, new_h) = if width <= height {
            (short_edge, (short_edge * height) / width)
        } else {
            ((short_edge * width) / height, short_edge)
        };
        (new_w, new_h)
    } else if args.width.is_some() && args.height.is_none() {
        let new_w = args.width.unwrap();
        let new_h = (new_w * height) / width;
        (new_w, new_h)
    } else if args.height.is_some() && args.width.is_none() {
        let new_h = args.height.unwrap();
        let new_w = (new_h * width) / height;
        (new_w, new_h)
    } else if let (Some(w), Some(h)) = (args.width, args.height) {
        (w, h)
    } else {
        (width, height)
    };

    if new_width == width && new_height == height {
        Ok(img)
    } else {
        Ok(img.resize_exact(new_width, new_height, image::imageops::FilterType::Lanczos3))
    }
}

fn preserve_timestamps(input_path: &Path, output_path: &Path) -> io::Result<()> {
    // In a real implementation, this would use filetime crate
    // For now, we'll skip this as it's platform-specific
    Ok(())
}

fn print_results(results: &[FileResult], verbose: u32) {
    let total = results.len();
    let success = results.iter().filter(|r| r.success && !r.skipped).count();
    let skipped = results.iter().filter(|r| r.skipped).count();
    let errors = total - success - skipped;

    let total_original: u64 = results.iter().map(|r| r.original_size).sum();
    let total_compressed: u64 = results.iter().map(|r| r.compressed_size).sum();
    let delta = (total_compressed as i64) - (total_original as i64);

    let percent = if total_original > 0 {
        (delta as f64 / total_original as f64) * 100.0
    } else {
        0.0
    };

    if verbose >= 1 {
        println!("Compressed {} files ({} success, {} skipped, {} errors)",
                 total, success, skipped, errors);

        let original_str = format_bytes(total_original);
        let compressed_str = format_bytes(total_compressed);
        let delta_str = if delta >= 0 {
            format!("+{}", format_bytes(delta as u64))
        } else {
            format!("-{}", format_bytes((-delta) as u64))
        };

        println!("{} -> {} [{} | {:.2}%]",
                 original_str, compressed_str, delta_str, percent);
    }
}

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}
