struct FileResult {
    input_path: PathBuf,
    output_path: PathBuf,
    original_size: u64,
    compressed_size: u64,
    success: bool,
    skipped: bool,
}

fn collect_input_files(paths: &[PathBuf], recursive: bool, verbose: u32) -> Vec<PathBuf> {
    let mut files = Vec::new();

    for path in paths {
        if path.is_file() {
            if is_supported_image(&path) {
                files.push(path.clone());
            }
        } else if path.is_dir() {
            if recursive {
                for entry in WalkDir::new(path)
                    .into_iter()
                    .filter_map(|e| e.ok())
                    .filter(|e| e.path().is_file())
                {
                    if is_supported_image(entry.path()) {
                        files.push(entry.path().to_path_buf());
                    }
                }
            } else {
                for entry in fs::read_dir(path).unwrap_or_default() {
                    if let Ok(entry) = entry {
                        let entry_path = entry.path();
                        if entry_path.is_file() && is_supported_image(&entry_path) {
                            files.push(entry_path);
                        }
                    }
                }
            }
        }
    }

    files
}

fn is_supported_image(path: &Path) -> bool {
    if let Some(ext) = path.extension() {
        if let Some(ext_str) = ext.to_str() {
            let lower = ext_str.to_lowercase();
            matches!(lower.as_str(), "jpg" | "jpeg" | "png" | "webp" | "gif" | "tif" | "tiff")
        } else {
            false
        }
    } else {
        false
    }
}

