            let entry_path = entry.path();
            if entry_path.is_file() && is_supported_image(&entry_path) {
                files.push(entry_path);
            } else if entry_path.is_dir() {
                collect_recursive(&entry_path, files);
            }
        }
    }
}

fn is_supported_image(path: &Path) -> bool {
