            "-e" | "--exif" => args.exif = true,
            "--keep-dates" => args.keep_dates = true,
            "--strip-icc" => args.strip_icc = true,
            "--suffix" => {
                if i + 1 < args_vec.len() {
                    args.suffix = Some(args_vec[i + 1].clone());
                    i += 1;
                }
            }
            "-R" | "--recursive" => args.recursive = true,
            "-S" | "--keep-structure" => args.keep_structure = true,
            "-d" | "--dry-run" => args.dry_run = true,
            "--threads" => {
                if i + 1 < args_vec.len() {
