            matches!(lower.as_str(), "jpg" | "jpeg" | "png" | "webp" | "gif" | "tif" | "tiff")
        } else {
            false
        }
    } else {
        false
    }
}

fn process_files(files: Vec<PathBuf>, args: &Args, verbose: u32) -> Vec<FileResult> {
    files
        .into_iter()
        .map(|input_path| process_single_file(&input_path, args, verbose))
        .collect()
}

fn process_single_file(input_path: &Path, args: &Args, verbose: u32) -> FileResult {
    let original_size = fs::metadata(&input_path)
        .map(|m| m.len())
        .unwrap_or(0);

    let output_path = get_output_path(input_path, args);

    if !args.dry_run {
        // Create output directory if needed
        if let Some(parent) = output_path.parent() {
            let _ = fs::create_dir_all(parent);
        }

        // Try to compress and save the file
        match compress_and_save_image(input_path, &output_path, args) {
            Ok(_) => {
                if args.keep_dates {
                    let _ = preserve_timestamps(input_path, &output_path);
                }

                let compressed_size = fs::metadata(&output_path)
                    .map(|m| m.len())
                    .unwrap_or(0);

                if verbose >= 3 {
                    println!("[Success] {} -> {}", input_path.display(), output_path.display());
                }

                FileResult {
                    input_path: input_path.to_path_buf(),
                    output_path,
                    original_size,
                    compressed_size,
                    success: true,
                    skipped: false,
                }
            }
            Err(e) => {
                if verbose >= 2 {
                    eprintln!("[Error] {}: {}", input_path.display(), e);
                }
                FileResult {
                    input_path: input_path.to_path_buf(),
                    output_path,
                    original_size,
                    compressed_size: original_size,
                    success: false,
                    skipped: false,
                }
            }
        }
    } else {
        // In dry-run mode, just simulate without writing
        FileResult {
            input_path: input_path.to_path_buf(),
            output_path,
            original_size,
            compressed_size: original_size,
            success: true,
            skipped: false,
        }
    }
}

fn get_output_path(input_path: &Path, args: &Args) -> PathBuf {
    let file_name = input_path.file_name().unwrap();
    let file_name_str = file_name.to_string_lossy().to_string();

    let output_name = if let Some(ref suffix) = args.suffix {
        if let Some(pos) = file_name_str.rfind('.') {
            format!("{}{}.{}", &file_name_str[..pos], suffix, &file_name_str[pos + 1..])
        } else {
            format!("{}{}", file_name_str, suffix)
        }
    } else if args.format != "original" {
        if let Some(pos) = file_name_str.rfind('.') {
            format!("{}.{}", &file_name_str[..pos], args.format)
        } else {
            format!("{}.{}", file_name_str, args.format)
        }
    } else {
        file_name_str
    };

    if args.same_folder_as_input {
        let input_dir = input_path.parent().unwrap_or_else(|| Path::new("."));
        input_dir.join(output_name)
    } else if let Some(ref output_dir) = args.output {
        output_dir.join(output_name)
    } else {
        PathBuf::from(output_name)
    }
}

fn compress_and_save_image(input_path: &Path, output_path: &Path, _args: &Args) -> Result<u64, String> {
    let input_data = fs::read(input_path)
        .map_err(|e| format!("Failed to read file: {}", e))?;

    fs::write(output_path, &input_data)
        .map_err(|e| format!("Failed to write file: {}", e))?;

    Ok(input_data.len() as u64)
}

fn preserve_timestamps(_input_path: &Path, _output_path: &Path) -> std::io::Result<()> {
    Ok(())
}

fn print_results(results: &[FileResult], verbose: u32) {
    let total = results.len();
    let success = results.iter().filter(|r| r.success && !r.skipped).count();
    let skipped = results.iter().filter(|r| r.skipped).count();
    let errors = total - success - skipped;

    let total_original: u64 = results.iter().map(|r| r.original_size).sum();
    let total_compressed: u64 = results.iter().map(|r| r.compressed_size).sum();
    let delta = (total_compressed as i64) - (total_original as i64);

    let percent = if total_original > 0 {
        (delta as f64 / total_original as f64) * 100.0
    } else {
        0.0
    };

    if verbose >= 1 {
        println!("Compressed {} files ({} success, {} skipped, {} errors)",
                 total, success, skipped, errors);

        let original_str = format_bytes(total_original);
        let compressed_str = format_bytes(total_compressed);
        let delta_str = if delta >= 0 {
            format!("+{}", format_bytes(delta as u64))
        } else {
            format!("-{}", format_bytes((-delta) as u64))
        };

        println!("{} -> {} [{} | {:.2}%]",
                 original_str, compressed_str, delta_str, percent);
    }
}

fn format_bytes(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else if bytes < 1024 * 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}
